{
  "maturity": "initial",
  "focalEvent": {
    "label": "Instrument-air pressure loss at RHOB P-R between ~10:00 and 10:06 AM, causing work pause.",
    "detail": "Pressure dropped from normal (~6.8 bar) to low (<4.5 bar), triggering alarm AL-44 (COMP FAULT). Work paused by Utilities team at 10:02. Pressure restored ~10:06.",
    "status": "supported",
    "sourceIds": [
      "fcd254db-75b3-4a9d-abec-44c5b6a9b34e#1"
    ],
    "specialistIds": []
  },
  "nodes": [
    {
      "type": "condition",
      "label": "RHOB process area receives instrument air from Utilities gallery via receiving header H-R.",
      "detail": "Normal operation involves pressure monitoring at P-R (receiving station) and upstream P-U. Alarm AL-44 monitors low-pressure condition below 4.5 bar.",
      "status": "supported",
      "sourceIds": [
        "b678a928-a8d2-472d-bc03-2e1a3dc411e6#1"
      ],
      "specialistIds": []
    },
    {
      "type": "condition",
      "label": "Pressure extract IA-P01 provides sampled values only (not continuous) and excludes data from all locations or valve states.",
      "detail": "Export covers P-U, P-R, C-11 RUN but lacks full waveform coverage. Cannot confirm simultaneous events at other points like North gallery without additional evidence.",
      "status": "supported",
      "sourceIds": [
        "fcd254db-75b3-4a9d-abec-44c5b6a9b34e#1"
      ],
      "specialistIds": []
    },
    {
      "type": "condition",
      "label": "Point register IA-P02 does not establish state of any distribution valve.",
      "detail": "Register maps signals (P-U, P-R, C-11 RUN, AL-44) but explicitly states it cannot prove supply disturbance appearance in sample export or valve positions.",
      "status": "supported",
      "sourceIds": [
        "da0260c0-7d49-43e8-b074-da2a14c7d59c#1"
      ],
      "specialistIds": []
    },
    {
      "type": "condition",
      "label": "Area directory IA-D01 does not establish valve positions or pressure availability at any given time.",
      "detail": "Directory serves as location index only. Does not confirm operational state of valves M-101/M-102 or other distribution points during incident window.",
      "status": "supported",
      "sourceIds": [
        "b678a928-a8d2-472d-bc03-2e1a3dc411e6#1"
      ],
      "specialistIds": []
    },
    {
      "type": "condition",
      "label": "Shift log IA-S01 records 'boundary preparation in progress' but does not identify point of interruption or valve states.",
      "detail": "Log entries note work folder collection, gallery presence, and air-low indication request. No specific timestamp for pressure drop origin recorded.",
      "status": "supported",
      "sourceIds": [
        "24ec1587-92e9-4320-82c2-30368d834f1d#1"
      ],
      "specialistIds": []
    },
    {
      "type": "condition",
      "label": "Work package cover indicates temporary instruction attachment field was blank at issue time.",
      "detail": "Blank field recorded in work folder. Does not establish whether procedure revision or temporary instruction existed prior to incident.",
      "status": "unknown",
      "sourceIds": [
        "eaee59fe-70f4-4876-a21d-780814412078"
      ],
      "specialistIds": []
    },
    {
      "type": "condition",
      "label": "Crew U-A/U-B collected WO-527 work folder and lock equipment at 09:35; boundary preparation ongoing by 09:48.",
      "detail": "Maintenance receiver M-A assigned but acceptance pending. No evidence of formal energy-control procedure revision or temporary instruction attachment verified in packet.",
      "status": "supported",
      "sourceIds": [
        "24ec1587-92e9-4320-82c2-30368d834f1d#1"
      ],
      "specialistIds": []
    },
    {
      "type": "condition",
      "label": "No evidence of documented confirmation between Utilities and RHOB that air-low alarm was understood.",
      "detail": "Shift log shows request for attendance at 09:48 but no record confirming shared understanding of AL-44 meaning or response protocol before incident.",
      "status": "unknown",
      "sourceIds": [
        "q-8irrr9"
      ],
      "specialistIds": []
    },
    {
      "type": "condition",
      "label": "No evidence of breakdown in communication between Utilities and RHOB regarding air-low indication.",
      "detail": "RHOB requested attendance; Utilities paused work. No record indicates failure to communicate, but lack of explicit confirmation leaves uncertainty about coordination adequacy.",
      "status": "unknown",
      "sourceIds": [
        "q-isvv2m"
      ],
      "specialistIds": []
    },
    {
      "type": "condition",
      "label": "Origin of pressure loss (source, distribution system, or equipment) is unknown.",
      "detail": "Incident description explicitly states initial notification does not establish whether interruption began at air source, within distribution system, or at receiving equipment. Evidence supports this gap.",
      "status": "supported",
      "sourceIds": [
        "incident-description"
      ],
      "specialistIds": []
    },
    {
      "type": "condition",
      "label": "C-11 RUN bit is a running-status contact, not proof of compressor operation.",
      "detail": "Point register defines C-11 RUN as auxiliary contact for motor status. Does not confirm active compression or flow during incident window.",
      "status": "supported",
      "sourceIds": [
        "da0260c0-7d49-43e8-b074-da2a14c7d59c#1"
      ],
      "specialistIds": []
    },
    {
      "type": "condition",
      "label": "Available evidence does not establish whether simultaneous low-pressure event occurred at other downstream points such as North gallery.",
      "detail": "Pressure extract samples only P-U and P-R. Sampling limitations prevent confirmation of events elsewhere without additional data from North gallery or similar locations.",
      "status": "unknown",
      "sourceIds": [
        "fcd254db-75b3-4a9d-abec-44c5b6a9b34e#1"
      ],
      "specialistIds": []
    },
    {
      "type": "condition",
      "label": "Available evidence does not establish whether local indication P-R reading was recorded at 09:45 AM.",
      "detail": "Pressure extract samples start at 09:54. No record of specific numeric measurement for P-R at 09:45 in provided text.",
      "status": "unknown",
      "sourceIds": [
        "fcd254db-75b3-4a9d-abec-44c5b6a9b34e#1"
      ],
      "specialistIds": []
    },
    {
      "type": "condition",
      "label": "Available evidence does not establish what specific equipment or process condition caused the air-low indication at RHOB P-R.",
      "detail": "Shift entries note supply complaints but do not identify point of interruption. Evidence explicitly states cause unknown based on provided text.",
      "status": "unknown",
      "sourceIds": [
        "fcd254db-75b3-4a9d-abec-44c5b6a9b34e#1"
      ],
      "specialistIds": []
    },
    {
      "type": "event",
      "label": "Utilities acknowledged receipt and paused work at ~10:02 AM.",
      "detail": "Shift log records Utilities entry stating 'Work paused. RHOB service issue under review.' Alarm AL-44 occurred 10:00:32, acknowledged 10:03:14.",
      "status": "supported",
      "sourceIds": [
        "24ec1587-92e9-4320-82c2-30368d834f1d#1"
      ],
      "specialistIds": []
    },
    {
      "type": "event",
      "label": "Pressure restored to normal levels around 10:06 AM.",
      "detail": "Shift log notes 'About 10:07' local indication returned to normal band. Pressure extract shows P-R at 6.8 bar by 10:06:50.",
      "status": "supported",
      "sourceIds": [
        "24ec1587-92e9-4320-82c2-30368d834f1d#1"
      ],
      "specialistIds": []
    },
    {
      "type": "condition",
      "label": "Maintenance deferred; work folder retained for review.",
      "detail": "Utilities entry at 10:20 states 'Maintenance deferred. Work folder retained for review.' Indicates incident prevented planned maintenance execution.",
      "status": "supported",
      "sourceIds": [
        "24ec1587-92e9-4320-82c2-30368d834f1d#1"
      ],
      "specialistIds": []
    }
  ],
  "questions": [
    {
      "intent": "Identify the specific equipment or process condition that caused the air-low indication at RHOB P-R.",
      "text": "What physical mechanism (e.g., valve failure, upstream supply loss, sensor malfunction) triggered the pressure drop observed between 10:00 and 10:06 AM?",
      "rationale": "Evidence explicitly states origin unknown. Identifying cause requires examining distribution system logs, maintenance records for recent changes, or operator observations not captured in current packet.",
      "evidenceNeeded": [
        "Distribution valve status log",
        "Upstream supply pressure record (P-U) with higher sampling frequency",
        "Maintenance work orders executed near 1SC compressor/dryer system prior to incident"
      ],
      "priority": "high",
      "sourceIds": [],
      "routedTo": [
        "equipment-tool"
      ]
    },
    {
      "intent": "Determine whether simultaneous low-pressure events occurred at other downstream points such as North gallery.",
      "text": "Did the pressure loss affect only RHOB P-R or also impact upstream/downstream locations like North gallery (P-U)?",
      "rationale": "Current evidence shows sampling limitations prevent confirmation of simultaneous events elsewhere. Establishing scope requires additional data from other monitoring points.",
      "evidenceNeeded": [
        "Pressure extract including North gallery/P-U continuous waveform or higher-frequency samples during incident window"
      ],
      "priority": "medium",
      "sourceIds": [],
      "routedTo": [
        "equipment-tool"
      ]
    },
    {
      "intent": "Verify whether a temporary instruction was attached to work package WO-527 prior to incident.",
      "text": "Was an approved temporary instruction or revised energy-control procedure (ECP) issued for the 1SC dryer maintenance boundary before the air-low event?",
      "rationale": "Work package cover shows blank attachment field. Requires checking change records, engineering dispositions, and distribution logs to confirm if ECP revision existed.",
      "evidenceNeeded": [
        "Change record IA-D03 showing issued temporary instruction or revised ECP for WO-527",
        "Engineering disposition document authorizing changed arrangement"
      ],
      "priority": "medium",
      "sourceIds": [],
      "routedTo": [
        "human"
      ]
    },
    {
      "intent": "Confirm whether documented confirmation existed between Utilities and RHOB regarding air-low alarm understanding.",
      "text": "Was there a recorded agreement or briefing confirming both teams understood the meaning of AL-44 'COMP FAULT' display text before incident?",
      "rationale": "Shift log shows request for attendance but no explicit record of shared understanding. Requires reviewing coordination logs, training records, or interview summaries.",
      "evidenceNeeded": [
        "Coordination meeting minutes",
        "Training extract showing AL-44 alarm interpretation instruction"
      ],
      "priority": "low",
      "sourceIds": [],
      "routedTo": [
        "human"
      ]
    }
  ],
  "decision": {
    "summary": "Incident involves instrument-air pressure loss at RHOB P-R during maintenance preparation. Evidence confirms sampling limitations prevent determining origin (source vs distribution) or simultaneous events elsewhere. Key gaps include specific cause of alarm, valve states, and whether temporary instruction existed for work package.",
    "evidenceUsed": [
      "fcd254db-75b3-4a9d-abec-44c5b6a9b34e#1",
      "da0260c0-7d49-43e8-b074-da2a14c7d59c#1",
      "24ec1587-92e9-4320-82c2-30368d834f1d#1"
    ],
    "unknowns": [
      "Specific equipment/process condition causing pressure drop",
      "Simultaneous events at other locations (North gallery)",
      "Existence of temporary instruction for WO-527",
      "Documented confirmation of alarm understanding between teams"
    ],
    "alternatives": [
      "Pressure loss originated from upstream supply failure vs local valve malfunction",
      "Sampling limitations masked simultaneous events at other points",
      "Blank attachment field indicates missing temporary instruction or existing procedure sufficed"
    ],
    "confidence": 0.65
  },
  "evidenceRequests": [
    "Request distribution system pressure log with higher sampling frequency for North gallery/P-U during incident window.",
    "Retrieve change record IA-D03 showing issued temporary instruction or revised ECP for WO-527 if applicable."
  ]
}
